        System.Threading.Tasks.Task<ApiResponse<InstallTrackingTagOnStore200Response>> InstallTrackingTagOnStoreWithHttpInfoAsync(string accountId, string tagId, InstallTrackingTagOnStoreRequest installTrackingTagOnStoreRequest, System.Threading.CancellationToken cancellationToken = default);
